import './style.css';
import { renderBadge } from './components/StatusBadge.js';
import { listRuns, retryRun, createRun, health } from './api/client.js';

// Shown only while /api/runs doesn't answer, and always labelled as sample data.
const SAMPLE_RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];
const ICON = { passed: '✓', failed: '✕', running: '●', queued: '○' };
const REFRESH_MS = 30_000;

const app = document.querySelector('#app');
const flashEl = document.querySelector('#flash');
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

// runs: undefined = loading, null = API didn't answer, array = live data.
let state = { connected: null, runs: undefined, updated: null };

function row(r, live) {
  const s = esc(r.status);
  return `<tr>
    <td class="mono">${esc(r.id)}</td>
    <td class="service">${esc(r.service)}</td>
    <td><span class="status status-${s}"><span aria-hidden="true">${ICON[r.status] ?? '•'}</span>${s}</span></td>
    <td class="num">${esc(r.started)}</td>
    <td class="num">${esc(r.duration)}</td>
    <td class="actions"><button class="btn btn-ghost retry" data-run="${esc(r.id)}"
      aria-label="Retry ${esc(r.id)}" ${live ? '' : 'disabled'}>Retry</button></td>
  </tr>`;
}

function body({ runs }) {
  if (runs === undefined) return `<tr><td colspan="6" class="empty">Loading runs…</td></tr>`;
  const live = runs !== null;
  const rows = live ? runs : SAMPLE_RUNS;
  if (!rows.length) return `<tr><td colspan="6" class="empty">No runs yet. Start one with New run.</td></tr>`;
  return rows.map((r) => row(r, live)).join('');
}

function render() {
  const live = Array.isArray(state.runs);
  app.innerHTML = `
    <header class="bar">
      <div class="title">
        <h1>pulse</h1><span class="sub">Deploy runs</span>
      </div>
      <div class="meta">
        ${renderBadge(state.connected)}
        ${state.updated ? `<span class="updated">Updated ${state.updated}</span>` : ''}
        <button id="new-run" class="btn btn-primary" ${live ? '' : 'disabled'}>New run</button>
      </div>
    </header>
    ${state.runs === null ? `<p class="notice">
      <strong>Sample data.</strong> The runs API isn't answering, so these rows aren't real
      and Retry / New run are turned off.</p>` : ''}
    <div class="card">
      <table>
        <caption class="sr-only">Recent deploy runs</caption>
        <thead><tr>
          <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
          <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
          <th scope="col"><span class="sr-only">Actions</span></th>
        </tr></thead>
        <tbody>${body(state)}</tbody>
      </table>
    </div>`;
}

async function load() {
  const [connected, runs] = await Promise.all([
    health().then(() => true, () => false),
    listRuns().then((d) => (Array.isArray(d) ? d : null), () => null),
  ]);
  state = { connected, runs, updated: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) };
  render();
}

function flash(kind, msg) {
  flashEl.className = `flash flash-${kind}`;
  flashEl.textContent = msg;
  clearTimeout(flash.t);
  flash.t = setTimeout(() => { flashEl.textContent = ''; flashEl.className = 'flash'; }, 6000);
}

async function act(btn, busyLabel, okMsg, call) {
  const label = btn.textContent;
  btn.disabled = true;
  btn.textContent = busyLabel;
  try {
    const res = await call();
    if (!res.ok) throw new Error(`server answered ${res.status}`);
    flash('ok', okMsg);
    await load();
  } catch (e) {
    flash('error', `${label} failed: ${e.message}`);
    btn.disabled = false;
    btn.textContent = label;
  }
}

// One delegated listener; survives re-renders.
app.addEventListener('click', (e) => {
  const btn = e.target.closest('button');
  if (!btn || btn.disabled) return;
  if (btn.id === 'new-run') {
    // ponytail: request body belongs to the backend ticket; {} until it's defined.
    act(btn, 'Starting…', 'New run started.', () => createRun({}));
  } else if (btn.classList.contains('retry')) {
    const id = btn.dataset.run;
    act(btn, 'Retrying…', `Retry of ${id} queued.`, () => retryRun(id));
  }
});

render();
load();
// ponytail: plain polling, which re-renders and drops focus. Swap for SSE/websocket when the backend has one.
setInterval(load, REFRESH_MS);

